"use strict";(self.webpackChunkmy_website=self.webpackChunkmy_website||[]).push([[35381],{32159:e=>{e.exports=JSON.parse('{"title":"reCamera Software","description":"The reCamera is a ready-to-use device right after startup. It comes with a stable reCamera OS that supports firmware OTA updates. Additionally, Node-RED and Sensecraft AI platform is integrated in the device for easier deployment experience. This integration offers novice developers a modular programming experience based on Node-RED nodes. For advanced developers, the in-depth Linux-based development and python are also there for twist and play. We warmly welcome developers proficient in JavaScript, C/C++, Python, Linux OS, buildroot, as well as geeks, students, and beginners, to engage in further development and explore applications.","slug":"recamera_software","permalink":"/recamera_software","navigation":{"previous":{"title":"Model Conversion Guide","permalink":"/recamera_model_conversion"},"next":{"title":"OS Version control","permalink":"/recamera_os_version_control"}}}')}}]);